INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What is ''hank'' in the context of yarn measurement?', '["A specific fixed length of yarn (840 yards for cotton) used as the basis for indirect count systems","The weight of one spindle of yarn","The color code applied to a batch of yarn","The number of twists per inch in a yarn"]'::jsonb, 'A specific fixed length of yarn (840 yards for cotton) used as the basis for indirect count systems', 'A hank is a standard length unit — 840 yards for the cotton (Ne) system — used to define indirect yarn count systems where count = number of hanks per unit weight.', 1, '{"hank","yarn-count"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'In the Tex direct count system, what does a HIGHER Tex number indicate about the yarn?', '["A coarser (thicker) yarn","A finer (thinner) yarn","A higher twist level only","Nothing related to yarn thickness"]'::jsonb, 'A coarser (thicker) yarn', 'Tex is a direct system: Tex = grams per 1000 meters of yarn. Since it directly measures mass per length, a HIGHER Tex number means MORE mass per length — a coarser yarn (opposite relationship to indirect systems like Ne).', 1, '{"tex-system"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What is the key difference between ''direct'' and ''indirect'' yarn count systems?', '["Direct systems (like Tex, denier) measure weight per fixed length; indirect systems (like Ne) measure length per fixed weight","Direct systems only apply to synthetic fiber, indirect only to cotton","There is no real difference between the two","Indirect systems are always more accurate than direct systems"]'::jsonb, 'Direct systems (like Tex, denier) measure weight per fixed length; indirect systems (like Ne) measure length per fixed weight', 'Direct systems express count as mass per unit length (Tex = g/1000m, denier = g/9000m) so higher number = coarser yarn; indirect systems express count as length per unit mass (Ne = hanks/lb) so higher number = finer yarn.', 1, '{"count-systems"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What is the primary purpose of applying a small amount of spin finish/oil to synthetic fiber before or during spinning?', '["To reduce friction and static electricity, improving fiber cohesion and processability","To permanently dye the fiber","To increase the fiber''s melting point","To eliminate the need for any twist"]'::jsonb, 'To reduce friction and static electricity, improving fiber cohesion and processability', 'Spin finish (a light oil/lubricant/antistatic treatment) reduces friction between fibers and machine parts and controls static buildup, improving fiber cohesion, handling, and smooth processing through spinning machinery.', 1, '{"spin-finish"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What does ''ends down'' or ''end breakage rate'' measure at the ring frame?', '["How frequently individual spinning positions experience a yarn break during production","The total number of spindles on the machine","The dye uptake rate of the yarn","The exact twist level of the yarn"]'::jsonb, 'How frequently individual spinning positions experience a yarn break during production', 'End breakage rate (ends down) tracks how often yarn breaks at spinning positions per unit time — a key efficiency/quality metric, since each break stops production at that position until the operator re-piecing occurs.', 1, '{"end-breakage"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'Why do spinning mills track ''spindle utilization'' or machine efficiency percentage?', '["To measure how much of the available production time spindles are actually running versus stopped (breaks, doffing, maintenance)","To measure the exact color of yarn produced","To measure fiber moisture content only","To track only the number of workers on shift"]'::jsonb, 'To measure how much of the available production time spindles are actually running versus stopped (breaks, doffing, maintenance)', 'Efficiency % reflects actual running time versus total available time; stoppages from end breaks, doffing (removing full bobbins), and maintenance all reduce efficiency and directly affect production output.', 1, '{"spindle-efficiency"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What happens during ''doffing'' at the ring frame?', '["Full bobbins of spun yarn are removed and replaced with empty bobbins so spinning can continue","Raw cotton bales are opened for the first time","Fiber is dyed before spinning begins","Twist is permanently removed from finished yarn"]'::jsonb, 'Full bobbins of spun yarn are removed and replaced with empty bobbins so spinning can continue', 'Doffing is the periodic process of removing bobbins that have been fully wound with yarn and replacing them with empty ones, allowing continuous spinning production (often automated on modern ring frames).', 1, '{"doffing"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What is a ''lea strength tester'' used to measure in spinning quality control?', '["The breaking strength of a specific hank/lea length of yarn","The color depth of dyed fabric","The moisture content of raw cotton bales","The number of spindles running on a machine"]'::jsonb, 'The breaking strength of a specific hank/lea length of yarn', 'A lea strength tester measures the breaking load of a lea (a specific standard length of yarn wound into a skein), a traditional quality-control method for assessing yarn strength.', 1, '{"lea-strength"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What does the Uster evenness tester primarily measure in yarn quality testing?', '["Mass variation (unevenness) along the yarn''s length, including thick places, thin places, and neps","The exact chemical composition of the fiber","The color fastness after washing","The twist direction (S or Z) only"]'::jsonb, 'Mass variation (unevenness) along the yarn''s length, including thick places, thin places, and neps', 'The Uster tester (capacitive sensor) continuously measures yarn mass per unit length as it passes through, quantifying unevenness (CV%), and classifying thick places, thin places, and neps by size/frequency.', 1, '{"uster-tester","evenness"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'In a comparison of two yarns with the same Uster CV% but different average imperfection (thick/thin/nep) counts, which yarn is generally considered better quality?', '["The one with fewer imperfections, since CV% alone doesn''t capture isolated severe faults","They are always equally good since CV% is identical","The one with more imperfections, since it shows more processing","Imperfection count is irrelevant if CV% is equal"]'::jsonb, 'The one with fewer imperfections, since CV% alone doesn''t capture isolated severe faults', 'CV% describes overall statistical variation, but distinct imperfections (thick places, thin places, neps) are separate localized faults that can be visually/functionally significant even if they don''t dominate the overall CV% — fewer imperfections generally means better practical quality.', 2, '{"yarn-quality","imperfections"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'A mill''s yarn strength test results show high variability (wide spread) between test samples, even though the average strength meets specification. What does this suggest?', '["Inconsistent processing (e.g., uneven drafting, twist, or fiber blending) creating weak spots, even though the average is acceptable","The testing equipment must be broken and results should be ignored entirely","High variability always means the yarn count is wrong","This is always a completely normal, ignorable a result requiring no investigation"]'::jsonb, 'Inconsistent processing (e.g., uneven drafting, twist, or fiber blending) creating weak spots, even though the average is acceptable', 'A good average strength can mask significant weak spots if variability is high — inconsistent processing (drafting waves, twist irregularity, poor fiber blending) can create localized weak points that increase breakage risk even when the average meets spec.', 2, '{"strength-variability"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'Why is ''fiber fineness'' (not just staple length) an important independent property for spinning quality, distinct from length?', '["Finer fibers allow more fibers to fit in a given yarn cross-section, improving evenness and enabling finer, smoother yarns even at similar staple length","Fiber fineness and staple length always vary together and are never independent","Fineness only matters for dyeing, not spinning performance","Fineness has no measurable effect on yarn quality"]'::jsonb, 'Finer fibers allow more fibers to fit in a given yarn cross-section, improving evenness and enabling finer, smoother yarns even at similar staple length', 'Fineness and length are independent fiber properties. For a given yarn count, finer fibers mean MORE fibers per cross-section (versus fewer, coarser fibers), which statistically improves evenness and allows smoother, higher-quality yarn — regardless of staple length.', 2, '{"fiber-fineness"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'What is the primary functional reason ring-frame roving bobbins are placed above the drafting zone on a creel, feeding downward into the drafting rollers?', '["This layout allows continuous, controlled unwinding of roving under light tension directly into the drafting zone without excessive handling","It is purely an aesthetic design choice with no functional basis","Roving must always be sprayed with water before entering rollers","Gravity has no role in any part of ring-frame operation"]'::jsonb, 'This layout allows continuous, controlled unwinding of roving under light tension directly into the drafting zone without excessive handling', 'The creel positions roving bobbins so roving unwinds smoothly and continuously (often assisted by gravity and light tensioning devices) directly into the drafting rollers, minimizing handling and maintaining consistent feed for even drafting.', 2, '{"ring-frame-creel"}'::text[]);
